package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;
@Document("seats") @CompoundIndex(name="flight_seat_unique",def="{'flightId':1,'seatNumber':1}",unique=true) public class Seat {public enum SeatClass{ECONOMY,PREMIUM_ECONOMY,BUSINESS,FIRST}public enum SeatType{WINDOW,MIDDLE,AISLE,EXIT_ROW}public enum Status{AVAILABLE,HELD,BOOKED,BLOCKED}@Id private String id;@Indexed private String flightId;private String seatNumber;private int row;private String column;private SeatClass seatClass;private SeatType seatType;private double price;private Status status=Status.AVAILABLE;private String bookingId;public String getId(){return id;}public String getFlightId(){return flightId;}public void setFlightId(String x){flightId=x;}public String getSeatNumber(){return seatNumber;}public void setSeatNumber(String x){seatNumber=x;}public int getRow(){return row;}public void setRow(int x){row=x;}public String getColumn(){return column;}public void setColumn(String x){column=x;}public SeatClass getSeatClass(){return seatClass;}public void setSeatClass(SeatClass x){seatClass=x;}public SeatType getSeatType(){return seatType;}public void setSeatType(SeatType x){seatType=x;}public double getPrice(){return price;}public void setPrice(double x){price=x;}public Status getStatus(){return status;}public void setStatus(Status x){status=x;}public String getBookingId(){return bookingId;}public void setBookingId(String x){bookingId=x;}}
